const trigger = $('Execute Workflow Trigger').first().json || {};
const txItems = $input.all();

// 1. Resilient input extraction (supports flat, nested target/newValues, or query wrapper)
let queryObj = {};
if (trigger.query) {
  if (typeof trigger.query === 'object') {
    queryObj = trigger.query;
  } else if (typeof trigger.query === 'string') {
    try { queryObj = JSON.parse(trigger.query); } catch(e) {}
  }
}

const sheetId = String(trigger.sheetId || queryObj.sheetId || trigger.documentId || queryObj.documentId || '').trim();
const action = String(trigger.action || queryObj.action || 'update').toLowerCase().trim();

const target = (trigger.target && typeof trigger.target === 'object') ? trigger.target : ((queryObj.target && typeof queryObj.target === 'object') ? queryObj.target : {});
const newValues = (trigger.newValues && typeof trigger.newValues === 'object') ? trigger.newValues : ((queryObj.newValues && typeof queryObj.newValues === 'object') ? queryObj.newValues : {});

const findLast = target.findLast === true || trigger.findLast === true || queryObj.findLast === true;
const targetTxId = String(target.transactionId || trigger.transactionId || queryObj.transactionId || '').trim();

const oldAmountRaw = target.oldAmount !== undefined && target.oldAmount !== null 
  ? target.oldAmount 
  : (trigger.oldAmount !== undefined && trigger.oldAmount !== null 
    ? trigger.oldAmount 
    : (queryObj.oldAmount !== undefined ? queryObj.oldAmount : null));
const oldAmount = (oldAmountRaw !== null && !isNaN(parseFloat(oldAmountRaw))) ? parseFloat(oldAmountRaw) : null;

const vendorOrItem = String(
  target.vendorOrItem || target.vendor || target.item || target.merchant ||
  trigger.vendorOrItem || trigger.vendor || trigger.item || trigger.merchant ||
  queryObj.vendorOrItem || queryObj.vendor || queryObj.item || queryObj.merchant || ''
).trim().toLowerCase();

// 2. Validate sheet data
if (txItems.length === 0 || !txItems[0].json || txItems[0].json.error) {
  return { 
    json: { 
      found: false, 
      action: action,
      sheetId: sheetId,
      response: "⚠️ Could not access your Transactions sheet. Please check your Google Sheet connection." 
    } 
  };
}

// 3. Filter active transactions
const validRows = txItems
  .map(item => item.json)
  .filter(r => r && r.row_number && r.amount !== undefined && String(r.type || '').toLowerCase() !== 'deleted');

if (validRows.length === 0) {
  return { 
    json: { 
      found: false, 
      action: action,
      sheetId: sheetId,
      response: "Your transaction sheet is currently empty. There are no active transactions to edit or delete." 
    } 
  };
}

// 4. Find matched transaction
let matchedRow = null;

// Exact transactionId match
if (targetTxId) {
  matchedRow = validRows.find(r => String(r.transactionId || '').trim() === targetTxId);
}

if (!matchedRow) {
  if (findLast && !vendorOrItem && oldAmount === null) {
    matchedRow = validRows[validRows.length - 1];
  } else {
    const reversed = [...validRows].reverse();
    const textMatches = (needle, rowV, rowD, rowC) => {
      if (!needle) return false;
      const cleanNeedle = needle.toLowerCase().replace(/[^a-z0-9]/g, '');
      if (!cleanNeedle) return false;
      const cleanStem = cleanNeedle.replace(/s$/, ''); // e.g. biscuits -> biscuit

      const v = String(rowV || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      const d = String(rowD || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      const c = String(rowC || '').toLowerCase().replace(/[^a-z0-9]/g, '');

      if (v.length > 0) {
        if (v.includes(cleanNeedle) || cleanNeedle.includes(v)) return true;
        if (cleanStem.length >= 3 && (v.includes(cleanStem) || cleanStem.includes(v))) return true;
      }
      if (d.length > 0) {
        if (d.includes(cleanNeedle) || cleanNeedle.includes(d)) return true;
        if (cleanStem.length >= 3 && (d.includes(cleanStem) || cleanStem.includes(d))) return true;
      }
      if (c.length > 0 && c.includes(cleanNeedle)) return true;
      return false;
    };

    // Priority 1: Match both amount AND vendor/item
    if (oldAmount !== null && vendorOrItem) {
      for (const row of reversed) {
        const rowAmt = parseFloat(String(row.amount || '').replace(/[^\d.]/g, '')) || 0;
        if (Math.abs(rowAmt - oldAmount) < 0.05 && textMatches(vendorOrItem, row.vendor, row.description, row.category)) {
          matchedRow = row;
          break;
        }
      }
    }

    // Priority 2: Match vendor/item alone
    if (!matchedRow && vendorOrItem) {
      for (const row of reversed) {
        if (textMatches(vendorOrItem, row.vendor, row.description, row.category)) {
          matchedRow = row;
          break;
        }
      }
    }

    // Priority 3: Match amount alone
    if (!matchedRow && oldAmount !== null) {
      for (const row of reversed) {
        const rowAmt = parseFloat(String(row.amount || '').replace(/[^\d.]/g, '')) || 0;
        if (Math.abs(rowAmt - oldAmount) < 0.05) {
          matchedRow = row;
          break;
        }
      }
    }

    // Priority 4: Fallback to last active transaction if findLast was requested
    if (!matchedRow && findLast) {
      matchedRow = validRows[validRows.length - 1];
    }
  }
}

if (!matchedRow) {
  const queryParts = [];
  if (oldAmount !== null) queryParts.push(`₹${oldAmount}`);
  if (vendorOrItem) queryParts.push(`"${vendorOrItem}"`);
  const queryStr = queryParts.join(' for ') || 'your specified details';

  return {
    json: {
      found: false,
      action: action,
      sheetId: sheetId,
      response: `Could not find any recent transaction matching ${queryStr}. Please check your transaction history!`
    }
  };
}

const origAmt = matchedRow.amount;
const origVendor = matchedRow.vendor || 'Unknown';
const origTxId = matchedRow.transactionId || ('txn_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7));

let finalRow = {};
let successMsg = '';

if (action === 'delete' || action === 'remove' || action === 'cancel') {
  finalRow = {
    row_number: matchedRow.row_number,
    transactionId: origTxId,
    date: matchedRow.date || new Date().toISOString().split('T')[0],
    amount: 0,
    vendor: `[DELETED] ${origVendor}`,
    category: matchedRow.category || 'Other',
    type: 'Deleted',
    medium: matchedRow.medium || 'other',
    description: `Deleted on ${new Date().toISOString().split('T')[0]}`
  };
  successMsg = `🗑️ Successfully removed transaction for ${origVendor} (₹${origAmt}) from your sheet!`;
} else {
  const updatedAmtRaw = newValues.amount !== undefined 
    ? newValues.amount 
    : (trigger.amount !== undefined 
      ? trigger.amount 
      : (queryObj.amount !== undefined 
        ? queryObj.amount 
        : (trigger.newAmount !== undefined ? trigger.newAmount : origAmt)));
  const updatedAmt = (updatedAmtRaw !== undefined && !isNaN(parseFloat(updatedAmtRaw))) ? parseFloat(updatedAmtRaw) : origAmt;

  const updatedVendor = newValues.vendor || newValues.vendorOrItem || trigger.newVendor || queryObj.newVendor || origVendor;
  const updatedCategory = newValues.category || trigger.newCategory || queryObj.newCategory || matchedRow.category || 'Other';
  const updatedDesc = newValues.description || trigger.description || queryObj.description || matchedRow.description || '';

  finalRow = {
    row_number: matchedRow.row_number,
    transactionId: origTxId,
    date: matchedRow.date || new Date().toISOString().split('T')[0],
    amount: updatedAmt,
    vendor: updatedVendor,
    category: updatedCategory,
    type: matchedRow.type || 'Expense',
    medium: matchedRow.medium || 'other',
    description: updatedDesc
  };
  successMsg = `✏️ Successfully updated transaction! Changed ${origVendor} (₹${origAmt}) to ${updatedVendor} (₹${updatedAmt}) under ${updatedCategory}.`;
}

return {
  json: {
    found: true,
    action: action,
    sheetId: sheetId,
    row_number: matchedRow.row_number,
    transactionId: origTxId,
    amount: finalRow.amount,
    vendor: finalRow.vendor,
    category: finalRow.category,
    response: successMsg,
    ...finalRow
  }
};

const item = $('Match & Prepare Change').item.json;
return {
  json: {
    status: 'SUCCESS',
    success: true,
    action: item.action || 'update',
    transactionId: item.transactionId,
    row_number: item.row_number,
    amount: item.amount,
    vendor: item.vendor,
    category: item.category,
    verified: true,
    response: item.response || 'Successfully updated transaction in your sheet!'
  }
};

const item = $input.first().json;
return {
  json: {
    status: 'NOT_FOUND',
    success: false,
    response: item.response || '⚠️ Correction Failed: Could not find any matching active transaction in your sheet.'
  }
};
